// specs/hal-engine-config-hooks/spec.md: a rejection JSON cannot serialise still reaches onError, its raw value kept as cause.
describe('asError on a value JSON cannot serialise', () => {
  it('wraps a circular rejection with a String() message and the raw value as cause', () => {
    const circular: Record<string, unknown> = {code: 503};
    circular.self = circular;
    const wrapped = asError(circular);

    expect({isError: wrapped instanceof Error, message: wrapped.message, sameCause: wrapped.cause === circular}).toEqual({
      isError: true,
      message: '[object Object]',
      sameCause: true,
    });
  });
});
EOF
